WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 1 HOUR THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, session_id, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, PERCENTILE_APPROX(humidity, 0.95) AS humidity_p95 FROM islands GROUP BY GROUPING SETS ((DATE_TRUNC('DAY', reading_ts), session_id), (DATE_TRUNC('DAY', reading_ts)))
